use crate::grid::P3;
use crate::sign::Sign;
use crate::wide::I256;

use super::{decide, exact_f64, larger, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^4 with E = 115u + 495u^2 + 792u^3 + 785u^4 + 549u^5 +
/// 254u^6 + 68u^7 + 8u^8, the result's unit error (header), rounded up to an `f64`:
/// 8092405580431372 · 2^-99.
const ERROR: f64 = f64::from_bits(0x3d0c_c000_0000_000c);

/// `line_sphere`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P3, b: P3, c: P3, r: i128) -> Option<Sign> {
    let d_x = exact_f64(b.x) - exact_f64(a.x);
    let d_y = exact_f64(b.y) - exact_f64(a.y);
    let d_z = exact_f64(b.z) - exact_f64(a.z);
    let w_x = exact_f64(a.x) - exact_f64(c.x);
    let w_y = exact_f64(a.y) - exact_f64(c.y);
    let w_z = exact_f64(a.z) - exact_f64(c.z);
    let u_x_1 = d_y * w_z;
    let u_x_2 = d_z * w_y;
    let u_x = u_x_1 - u_x_2;
    let u_y_1 = d_z * w_x;
    let u_y_2 = d_x * w_z;
    let u_y = u_y_1 - u_y_2;
    let u_z_1 = d_x * w_y;
    let u_z_2 = d_y * w_x;
    let u_z = u_z_1 - u_z_2;
    let dd_1 = d_x * d_x;
    let dd_2 = d_y * d_y;
    let dd_3 = dd_1 + dd_2;
    let dd_4 = d_z * d_z;
    let dd = dd_3 + dd_4;
    let uu_1 = u_x * u_x;
    let uu_2 = u_y * u_y;
    let uu_3 = uu_1 + uu_2;
    let uu_4 = u_z * u_z;
    let uu = uu_3 + uu_4;
    let r = rounded_f64(r, 41)?;
    let delta_1 = r * r;
    let delta_2 = delta_1 * dd;
    let delta = delta_2 - uu;
    let m_x = largest_magnitude([d_x, w_x]);
    let m_y = largest_magnitude([d_y, w_y]);
    let m_z = largest_magnitude([d_z, w_z]);
    let m_r = largest_magnitude([r]);
    let scale = larger(m_z * m_z * m_r * m_r, m_y * m_y * m_r * m_r);
    let scale = larger(scale, m_y * m_y * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_r * m_r);
    let scale = larger(scale, m_x * m_x * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_y * m_y);
    decide(delta, ERROR, scale)
}

/// `line_sphere`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(a: P3, b: P3, c: P3, r: i128) -> Option<I256> {
    let d_x = b.x.get().checked_sub(a.x.get())?;
    let d_y = b.y.get().checked_sub(a.y.get())?;
    let d_z = b.z.get().checked_sub(a.z.get())?;
    let w_x = a.x.get().checked_sub(c.x.get())?;
    let w_y = a.y.get().checked_sub(c.y.get())?;
    let w_z = a.z.get().checked_sub(c.z.get())?;
    let u_x_1 = i128::from(d_y).checked_mul(i128::from(w_z))?;
    let u_x_2 = i128::from(d_z).checked_mul(i128::from(w_y))?;
    let u_x = u_x_1.checked_sub(u_x_2)?;
    let u_y_1 = i128::from(d_z).checked_mul(i128::from(w_x))?;
    let u_y_2 = i128::from(d_x).checked_mul(i128::from(w_z))?;
    let u_y = u_y_1.checked_sub(u_y_2)?;
    let u_z_1 = i128::from(d_x).checked_mul(i128::from(w_y))?;
    let u_z_2 = i128::from(d_y).checked_mul(i128::from(w_x))?;
    let u_z = u_z_1.checked_sub(u_z_2)?;
    let dd_1 = i128::from(d_x).checked_mul(i128::from(d_x))?;
    let dd_2 = i128::from(d_y).checked_mul(i128::from(d_y))?;
    let dd_3 = dd_1.checked_add(dd_2)?;
    let dd_4 = i128::from(d_z).checked_mul(i128::from(d_z))?;
    let dd = dd_3.checked_add(dd_4)?;
    let uu_1 = I256::product_i128(u_x, u_x)?;
    let uu_2 = I256::product_i128(u_y, u_y)?;
    let uu_3 = uu_1.checked_add(&uu_2)?;
    let uu_4 = I256::product_i128(u_z, u_z)?;
    let uu = uu_3.checked_add(&uu_4)?;
    let r = i64::try_from(within(r, 41)?).ok()?;
    let delta_1 = i128::from(r).checked_mul(i128::from(r))?;
    let delta_2 = I256::product_i128(delta_1, dd)?;
    let delta = delta_2.checked_sub(&uu)?;
    Some(delta)
}

/// `line_sphere`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(a: P3, b: P3, c: P3, r: i128) -> Option<Sign> {
    value(a, b, c, r).map(|v| v.signum())
}
